<?php
class PropertyController extends Controller{private function model(){require_once __DIR__.'/../models/Property.php';return new Property();}private function formData(){require_once __DIR__.'/../models/Host.php';require_once __DIR__.'/../models/Location.php';return [(new Host())->all(),(new Location())->all()];}public function index(){require_login();$properties=$this->model()->all(['search'=>$_GET['search']??'','max_price'=>$_GET['max_price']??'','location_id'=>$_GET['location_id']??'']);require_once __DIR__.'/../models/Location.php';$locations=(new Location())->all();$this->view('properties/index',compact('properties','locations'));}public function create(){require_role(['Admin','Host']);[$hosts,$locations]=$this->formData();$this->view('properties/form',['property'=>null,'hosts'=>$hosts,'locations'=>$locations,'action'=>url('properties/store')]);}public function store(){verify_csrf();require_role(['Admin','Host']);$this->model()->create($this->data());Session::flash('success','Property created.');$this->redirect('properties');}public function edit(){require_role(['Admin','Host']);[$hosts,$locations]=$this->formData();$property=$this->model()->find($_GET['id']);$this->view('properties/form',['property'=>$property,'hosts'=>$hosts,'locations'=>$locations,'action'=>url('properties/update?id='.$_GET['id'])]);}public function update(){verify_csrf();require_role(['Admin','Host']);$this->model()->update($_GET['id'],$this->data());Session::flash('success','Property updated.');$this->redirect('properties');}public function delete(){require_role(['Admin','Host']);$this->model()->delete($_GET['id']);Session::flash('success','Property deleted.');$this->redirect('properties');}private function data(){return ['host_id'=>$_POST['host_id'],'location_id'=>$_POST['location_id'],'title'=>$_POST['title'],'property_type'=>$_POST['property_type'],'address'=>$_POST['address'],'bedrooms'=>(int)$_POST['bedrooms'],'bathrooms'=>(int)$_POST['bathrooms'],'price_per_month'=>(float)$_POST['price_per_month'],'availability_status'=>$_POST['availability_status'],'image_path'=>$_POST['image_path']?:'assets/images/property1.svg','description'=>$_POST['description']??''];}}
